#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#define int long long
#define PB push_back
#define MP make_pair
#define FI first
#define SE second
using namespace std;

static const int INF = 1ll << 60;
typedef pair<int, int> pii;

int W, H, N;
vector<int> posx, posy;
vector<pii> pos;

int dist(int x, int y) {
    int max_dist = 0;
    int total_distance = 0;
    for (int i = 0; i < N; ++i) {
        int d = abs(x - pos[i].FI) + abs(y - pos[i].SE);
        max_dist = max(max_dist, d);
        total_distance += d;
    }
    return max_dist + 2 * (total_distance - max_dist);
}

signed main() {
    cin >> W >> H >> N;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        posx.PB(x);
        posy.PB(y);
        pos.PB(pii(x, y));
    }
    sort(posx.begin(), posx.end());
    sort(posy.begin(), posy.end());
    int x, y, ans = INF;

    if (N % 2 != 0) {
        x = posx[N / 2];
        y = posy[N / 2];
    } else {
        int d1 = dist(posx[N / 2 - 1], posy[N / 2 - 1]);
        int d2 = dist(posx[N / 2 - 1], posy[N / 2]);
        int d3 = dist(posx[N / 2], posy[N / 2 - 1]);
        int d4 = dist(posx[N / 2], posy[N / 2]);
        ans = min({d1, d2, d3, d4});
        if (ans == d1) { x = posx[N / 2 - 1]; y = posy[N / 2 - 1]; }
        else if (ans == d2) { x = posx[N / 2 - 1]; y = posy[N / 2]; }
        else if (ans == d3) { x = posx[N / 2]; y = posy[N / 2 - 1]; }
        else { x = posx[N / 2]; y = posy[N / 2]; }
    }
    cout << dist(x, y) << endl << x << " " << y << endl;
}

