    for (int i = 0; i < N; ++i) {
        dis[i] = abs(x - pos[i].FI) + abs(y - pos[i].SE);
    }
    sort(dis, dis + N);
    return dis[N - 1] + 2 * accumulate(dis, dis + N - 1, 0LL);
}

signed main() {
